    // Discord channel where finished posts arrive (Channel settings → Integrations → Webhooks)
    discordWebhook: 'https://discord.com/api/webhooks/REPLACE_ME',
    // Card renderer on the SyncBatch site (its secret lives in the "SyncBatch card secret" credential)
