    siteUrl: 'https://syncbatch.inovuslabs.org',
    // Optional: @mention yourself on every post, e.g. '<@123456789012345678>' (leave '' for none)
    mention: '',
    // Free models, tried in this order. Each has its own free quota.
    geminiPrimary: 'gemini-3.8-flash',
    geminiBackup: 'gemini-3.5-flash-lite',
    groqModel: 'openai/gpt-oss-120b',
  },
}];

// Decides WHAT this run posts, and whether it should run at all.
// History lives in this workflow's static data (kept between production runs;
// manual test runs don't save it).
const store = $getWorkflowStaticData('global');
store.history = store.history || [];

// Date in IST, so the 09:00 and 18:00 runs share one slot.
const slotKey = new Date().toLocaleDateString('en-CA', { timeZone: 'Asia/Kolkata' });

// The 18:00 catch-up run does nothing if this morning's post already went out.
if (store.history.some((h) => h.slotKey === slotKey && h.status)) {
  return [];
}

// Topic rotation. Each pillar names the layouts that suit it.
const PILLARS = [
  { id: 'teachers', audience: 'school and college teachers, class coordinators', angle: 'class or parent list → contacts → WhatsApp group', templates: ['statement', 'steps', 'beforeafter'] },
  { id: 'tips', audience: 'anyone who saves many numbers', angle: 'one practical, true tip about contacts, country codes, WhatsApp visibility, labels, iPhone .vcf, or removing a batch later', templates: ['tip'] },
  { id: 'events', audience: 'college fest, conference and event organisers', angle: 'registration or attendee list (Google Forms, ticketing CSV) → team phones', templates: ['beforeafter', 'statement'] },
  { id: 'coaching', audience: 'coaching centres and tuition teachers', angle: 'new batches every month, labelled and removable later', templates: ['usecase', 'steps'] },
  { id: 'maker', audience: 'students, makers, LinkedIn network', angle: 'build in public: why a KJCMT student built SyncBatch at INOVUS LABS IEDC, a decision or lesson from building it (no invented metrics)', templates: ['statement', 'usecase'] },
  { id: 'sales', audience: 'small sales, real estate and recruitment teams', angle: 'lead or client list → caller ID, with a campaign label, removed after the campaign', templates: ['usecase', 'beforeafter'] },
  { id: 'trust', audience: 'people wary of giving a website their contacts', angle: 'what happens to your data: personal syncs not stored, official Google People API, preview before anything syncs', templates: ['usecase', 'tip'] },
  { id: 'howto', audience: 'first-time visitors', angle: 'the whole flow in three steps, Android and iPhone', templates: ['steps'] },
];

const n = store.history.length;
const pillar = PILLARS[n % PILLARS.length];
// Avoid repeating the last layout used.
const lastTemplate = store.history.at(-1)?.template;
const template = pillar.templates.find((t) => t !== lastTemplate) || pillar.templates[0];

const recent = store.history.slice(-40);

return [{
  json: {
    slotKey,
    pillar: pillar.id,
    audience: pillar.audience,
    angle: pillar.angle,
    template,
    recentHeadlines: recent.map((h) => `${h.headline} ${h.highlight || ''}`.trim()),
    recentAngles: recent.map((h) => h.angleSummary).filter(Boolean),
    usedFallbackIds: store.history.map((h) => h.fallbackId).filter(Boolean),
  },
}];

// Builds one prompt and the request body for each free model. The fact sheet is the only source of product claims.
const plan = $input.first().json;
const cfg = $('Config').first().json;

const SYSTEM = `You write social posts for SyncBatch, a web app built by a student maker at INOVUS LABS IEDC (Kristu Jyoti College of Management and Technology, Changanassery, Kerala, India). The audience is mainly in India: teachers, coaching centres, event organisers, small sales teams.

FACT SHEET — the only product claims you may make:
- Upload an Excel (.xlsx, .xls) or CSV file, or paste a public Google Sheets link.
- SyncBatch finds the name and phone columns, flags invalid numbers, and skips duplicate numbers in the file. You can edit or untick contacts in a preview before anything syncs.
- Numbers without a country code get the default country you pick (India +91 preselected; US & Canada, UK, UAE, Saudi Arabia, Qatar, Kuwait, Oman, Bahrain, Singapore, Malaysia, Australia, Germany, France and others). Leading zeros are removed. Numbers that already start with + are kept.
- Android: contacts go to the user's own Google Contacts through Google's official People API, in batches of 200. Numbers already in their Google Contacts are skipped.
- iPhone: download one .vcf file; opening it on the iPhone (AirDrop, Files, Mail) lets iOS add all contacts at once. No app to install.
- Add a label before or after every name, e.g. "(Class 12-A)" or "[Lead Q4]".
- Remove a batch later: upload the same sheet in "Delete contacts" mode; contacts are matched by phone number.
- WhatsApp shows people saved in the phone's contacts, so after syncing, people appear in WhatsApp (refresh contacts) and you can make a group.
- Only the name and one phone number per row are saved.
- Personal syncs are not stored by SyncBatch. Exception: the Institutional Hub, where an admin sends one list to members, keeps that list so members can accept it.
- Pricing: first 10 contacts free, no card. Credit packs: ₹49 for 300 contacts, ₹109 for 750 contacts (US$3 / US$5 outside India). Credits never expire. No subscription. Payments via Razorpay (UPI, cards, net banking in India).

NEVER: invent user counts, ratings, reviews, testimonials, quotes, results, percentages or time saved beyond "minutes instead of an hour"; claim GDPR/CCPA or any compliance; claim column mapping, emails or extra fields sync, unlimited anything, "190+ countries", or features not listed; offer discounts or deadlines; use fake urgency; mention competitors by name.

VOICE: plain, warm, specific, sentence case. Short sentences. Talk about the reader's real situation (a class list, a fest registration sheet, a new batch). Banned words: seamless, effortless, ultimate, revolutionary, game-changer, unlock, supercharge, leverage, elevate, enterprise-grade, "in today's world". Emojis: at most 2 per caption, none on the card.

CARD FIELDS (rendered on a 1080x1350 image; the card already shows both logos, the website and a button):
- eyebrow: 1–4 words naming the audience or topic.
- headline + highlight: read together as one sentence; highlight (the blue part) is the last 1–4 words. Together max 55 characters.
- body: one or two sentences, max 150 characters.
- points: for "steps" exactly 3 short steps (max 45 chars each); for "usecase" exactly 3 short benefits (max 45 chars); for "tip" exactly 1 sentence (max 120 chars) that states the tip; otherwise [].
- before/after: only for "beforeafter" (max 80 chars each); otherwise "".
- cta: 2–5 words, e.g. "Try it free", "Preview your list free".

CAPTIONS:
- instagram_caption: hook line, 2–4 short lines, ends with "Link in bio." Max 700 characters. No URL.
- linkedin_post: 4–8 short lines, first-person from Amith (the maker) when it fits, ends with the line "{LINK}" where the link goes. Max 1100 characters.
- x_post: max 200 characters, ends with "{LINK}".
- hashtags: instagram 8–12 (mix broad, niche and Kerala/India), linkedin 3–5, x 1–2. Without the # sign. Always include SyncBatch and InovusLabs in instagram and linkedin.
- alt_text: describes the card image for screen readers, max 200 characters.
- angle_summary: 8–15 words describing this post's idea, used to avoid repeats.`;

const user = `Write 3 different candidate posts for ${plan.slotKey}.
Topic pillar: ${plan.pillar}
Audience: ${plan.audience}
Angle: ${plan.angle}
Card layout (template): ${plan.template}

Every candidate must be clearly different from these recent headlines:
${plan.recentHeadlines.length ? plan.recentHeadlines.map((h) => `- ${h}`).join('\n') : '- (none yet)'}

And take a different idea from these recent angles:
${plan.recentAngles.length ? plan.recentAngles.map((a) => `- ${a}`).join('\n') : '- (none yet)'}

Make the 3 candidates different from each other too (different hook, different situation).`;

const str = { type: 'string' };
const strArr = { type: 'array', items: str };
const FIELDS = ['eyebrow', 'headline', 'highlight', 'body', 'points', 'before', 'after', 'cta', 'instagram_caption', 'linkedin_post', 'x_post', 'hashtags', 'alt_text', 'angle_summary'];
const candidate = {
  type: 'object',
  additionalProperties: false,
  required: FIELDS,
  properties: {
    eyebrow: str, headline: str, highlight: str, body: str, points: strArr, before: str, after: str, cta: str,
    instagram_caption: str, linkedin_post: str, x_post: str,
    hashtags: {
      type: 'object', additionalProperties: false, required: ['instagram', 'linkedin', 'x'],
      properties: { instagram: strArr, linkedin: strArr, x: strArr },
    },
    alt_text: str, angle_summary: str,
  },
};
const schema = {
  type: 'object', additionalProperties: false, required: ['candidates'],
  properties: { candidates: { type: 'array', items: candidate } },
};

// Gemini's responseSchema uses an OpenAPI-style subset: upper-case types, no additionalProperties.
const toGemini = (s) => {
  const out = { type: s.type.toUpperCase() };
  if (s.properties) {
    out.properties = Object.fromEntries(Object.entries(s.properties).map(([k, v]) => [k, toGemini(v)]));
    out.required = s.required;
    out.propertyOrdering = Object.keys(s.properties);
  }
  if (s.items) out.items = toGemini(s.items);
  return out;
};

const geminiBody = {
  systemInstruction: { parts: [{ text: SYSTEM }] },
  contents: [{ role: 'user', parts: [{ text: user }] }],
  generationConfig: {
    responseMimeType: 'application/json',
    responseSchema: toGemini(schema),
    maxOutputTokens: 16384,
  },
};

const groqBody = {
  model: cfg.groqModel,
  messages: [{ role: 'system', content: SYSTEM }, { role: 'user', content: user }],
  response_format: { type: 'json_schema', json_schema: { name: 'social_posts', strict: true, schema } },
  reasoning_effort: 'low',
  max_completion_tokens: 6000,
};

return [{ json: { ...plan, geminiBody, groqBody } }];

// Reads one model's reply and picks the first candidate that isn't a repeat.
// Throwing here passes the run to the next free model (error output).
const PROVIDER = 'Gemini Flash';
const SHAPE = 'gemini'; // 'gemini' or 'openai'
const res = $input.first().json;
const plan = $('Build prompt').first().json;

let text = '';
if (SHAPE === 'gemini') {
  const cand = (res.candidates || [])[0];
  if (!cand) throw new Error(`${PROVIDER}: no answer (${res.promptFeedback?.blockReason || 'empty response'})`);
  if (cand.finishReason && cand.finishReason !== 'STOP') throw new Error(`${PROVIDER}: stopped early (${cand.finishReason})`);
  text = (cand.content?.parts || []).filter((p) => !p.thought && typeof p.text === 'string').map((p) => p.text).join('');
} else {
  const choice = (res.choices || [])[0];
  if (!choice) throw new Error(`${PROVIDER}: no answer`);
  if (choice.finish_reason && choice.finish_reason !== 'stop') throw new Error(`${PROVIDER}: stopped early (${choice.finish_reason})`);
  text = choice.message?.content || '';
}
if (!text) throw new Error(`${PROVIDER}: returned no text`);

let candidates;
try {
  candidates = JSON.parse(text.replace(/^\s*```(?:json)?\s*|\s*```\s*$/g, '')).candidates;
} catch {
  throw new Error(`${PROVIDER}: returned invalid JSON`);
}
if (!Array.isArray(candidates) || !candidates.length) throw new Error(`${PROVIDER}: returned no candidates`);

const words = (s) => new Set(String(s).toLowerCase().replace(/[^a-z0-9₹ ]/g, ' ').split(/\s+/).filter((w) => w.length > 2));
const similarity = (a, b) => {
  const A = words(a); const B = words(b);
  if (!A.size || !B.size) return 0;
  let common = 0;
  for (const w of A) if (B.has(w)) common++;
  return common / Math.min(A.size, B.size);
};

const BANNED = /\b(seamless|effortless|ultimate|revolutionary|game[- ]changer|unlock|supercharge|leverage|elevate|enterprise-grade|gdpr|ccpa|190\+|unlimited|testimonial|rated|\d+(,\d{3})*\+? (users|customers|teachers|happy))\b/i;

const problems = [];
const valid = candidates.filter((c, i) => {
  const headline = `${c.headline} ${c.highlight}`.trim();
  const all = [headline, c.body, c.instagram_caption, c.linkedin_post, c.x_post, ...(c.points || []), c.before, c.after].join(' ');
  const why = [];
  if (!c.headline) why.push('no headline');
  if (headline.length > 70) why.push('headline too long');
  if (BANNED.test(all)) why.push(`banned claim "${all.match(BANNED)[0]}"`);
  const closest = Math.max(0, ...plan.recentHeadlines.map((h) => similarity(headline, h)));
  if (closest >= 0.6) why.push('too close to a recent headline');
  const angleRepeat = Math.max(0, ...plan.recentAngles.map((a) => similarity(c.angle_summary, a)));
  if (angleRepeat >= 0.7) why.push('repeats a recent angle');
  if (plan.template === 'steps' && (c.points || []).length < 3) why.push('steps needs 3 points');
  if (plan.template === 'beforeafter' && (!c.before || !c.after)) why.push('missing before/after');
  if (why.length) problems.push(`#${i + 1}: ${why.join(', ')}`);
  return !why.length;
});

if (!valid.length) throw new Error(`${PROVIDER}: no usable candidate (${problems.join('; ')})`);

return [{
  json: {
    source: PROVIDER,
    note: problems.length ? `Skipped ${problems.length} candidate(s): ${problems.join('; ')}` : '',
    post: valid[0],
  },
}];

