// One shape for every path (any free model, or the backup bank): card request, captions with tracked links,
// and the Discord message.
const plan = $('Build prompt').first().json;
const cfg = $('Config').first().json;
const { source, note, post, fallbackId } = $input.first().json;
const template = $input.first().json.template || plan.template;
const footer = [
  source !== 'Gemini Flash' && source !== 'backup' ? `Gemini Flash was unavailable, so ${source} wrote this.` : '',
  note || '',
  `Written by ${source === 'backup' ? 'the backup bank' : source} · ${plan.slotKey}`,
].filter(Boolean).join(' ');

const campaign = `weekly_${plan.slotKey}`;
const link = (src) => `${cfg.siteUrl}/?utm_source=${src}&utm_medium=social&utm_campaign=${campaign}`;

const tags = (list, must, max) => {
  const clean = [...must, ...(list || [])]
    .map((t) => String(t).replace(/[^\p{L}\p{N}_]/gu, ''))
    .filter(Boolean);
  return [...new Map(clean.map((t) => [t.toLowerCase(), t])).values()].slice(0, max).map((t) => `#${t}`).join(' ');
};

const ig = `${post.instagram_caption.replace(/\{LINK\}/g, '').trim()}\n\n${tags(post.hashtags?.instagram, ['SyncBatch', 'InovusLabs'], 12)}`;
const li = `${post.linkedin_post.replace(/\{LINK\}/g, link('linkedin')).trim()}\n\n${tags(post.hashtags?.linkedin, ['SyncBatch', 'InovusLabs'], 5)}`;
// X counts every link as 23 characters; keep the whole post under 280.
let xTags = tags(post.hashtags?.x, [], 2);
const xBase = post.x_post.includes('{LINK}') ? post.x_post : `${post.x_post} {LINK}`;
const xLen = (t) => xBase.replace('{LINK}', '').length + 23 + (t ? t.length + 1 : 0);
while (xTags && xLen(xTags) > 280) xTags = xTags.split(' ').slice(0, -1).join(' ');
const x = `${xBase.replace('{LINK}', link('x'))}${xTags ? ` ${xTags}` : ''}`;

const card = {
  template,
  eyebrow: post.eyebrow, headline: post.headline, highlight: post.highlight, body: post.body,
  points: post.points || [], before: post.before || '', after: post.after || '', cta: post.cta,
};

const day = new Date(`${plan.slotKey}T00:00:00+05:30`).toLocaleDateString('en-IN', { weekday: 'long', day: 'numeric', month: 'short', timeZone: 'Asia/Kolkata' });
const cut = (s, n) => (s.length > n ? `${s.slice(0, n - 1)}…` : s);

const discord = {
  username: 'SyncBatch content',
  content: cut(`${cfg.mention ? `${cfg.mention} ` : ''}**New post ready — ${day}** · ${plan.pillar} · ${template}${source === 'backup' ? ' · ⚠️ backup copy' : ''}\nInstagram bio link: ${link('instagram')}`, 1900),
  embeds: [
    { title: 'Instagram caption', description: cut(ig, 4000), color: 0x2e5bff, image: { url: 'attachment://card.png' } },
    { title: 'LinkedIn post', description: cut(li, 4000), color: 0x0a66c2 },
    { title: 'X post', description: cut(x, 1000), color: 0x0f172a },
    { title: 'Alt text', description: cut(post.alt_text || '', 500) || '—', color: 0x64748b, footer: { text: cut(footer, 2000) } },
  ],
  allowed_mentions: { parse: ['users'] },
};

return [{
  json: {
    slotKey: plan.slotKey, pillar: plan.pillar, template, source, fallbackId: fallbackId || null,
    headline: post.headline, highlight: post.highlight, angleSummary: post.angle_summary,
    card, discord,
  },
}];

// Discord shows the image inside the embed only if the attachment name matches "attachment://card.png".
const item = $input.first();
item.binary.data.fileName = 'card.png';
item.binary.data.mimeType = 'image/png';
return [item];

// Card rendering failed even after retries: still deliver the captions, without an image.
const f = $('Finalize post').first().json;
const err = $input.first().json.error;
const reason = (typeof err === 'string' ? err : err?.message) || 'unknown error';
const discord = JSON.parse(JSON.stringify(f.discord));
delete discord.embeds[0].image;
discord.content = `${discord.content}\n⚠️ **The card image couldn't be rendered** (${reason.slice(0, 200)}). Captions are below; use one of the Product Hunt gallery images, or re-run the workflow.`.slice(0, 2000);
return [{ json: { discord } }];

// Records the post so later runs avoid repeating it, and so the 18:00 catch-up run skips this slot.
const f = $('Finalize post').first().json;
const store = $getWorkflowStaticData('global');
store.history = store.history || [];
const status = $('Send card to Discord').isExecuted ? 'sent' : 'text_only';
store.history.push({
  slotKey: f.slotKey, status, pillar: f.pillar, template: f.template, source: f.source,
  fallbackId: f.fallbackId, headline: f.headline, highlight: f.highlight, angleSummary: f.angleSummary,
  at: new Date().toISOString(),
});
store.history = store.history.slice(-120);
return [{ json: { saved: true, status, total: store.history.length } }];
